import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { Resvg } from "@resvg/resvg-js";

const fontFile = fileURLToPath(new URL("./fonts/SpaceGrotesk.ttf", import.meta.url));
const logo = readFileSync(new URL("../public/logo.svg", import.meta.url), "utf8");
const escapeXml = (value) => String(value).replace(/[<>&"']/g, (c) => ({
  "<": "&lt;", ">": "&gt;", "&": "&amp;", '"': "&quot;", "'": "&apos;",
})[c]);

// Keep long titles and unbroken command names inside the card's text column.
export function wrapTitle(title, width = 25) {
  const words = String(title).trim().split(/\s+/).flatMap((word) => {
    const letters = Array.from(word);
    const chunks = [];
    for (let i = 0; i < letters.length; i += width) chunks.push(letters.slice(i, i + width).join(""));
    return chunks;
  });
  const lines = [];
  let line = "";
  for (const word of words) {
    if (line && Array.from(`${line} ${word}`).length > width) {
      lines.push(line);
      line = word;
    } else line = line ? `${line} ${word}` : word;
  }
  if (line) lines.push(line);
  if (lines.length > 4) return [...lines.slice(0, 3), `${Array.from(lines[3]).slice(0, width - 1).join("")}…`];
  return lines;
}

export function socialCard(title) {
  const lines = wrapTitle(title);
  const size = lines.length > 3 ? 54 : 62;
  const start = 298 - ((lines.length - 1) * (size + 14)) / 2;
  const heading = lines.map((line, i) => `<text x="64" y="${start + i * (size + 14)}" font-size="${size}" fill="#f4eee3">${escapeXml(line)}</text>`).join("");
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="1200" height="630" viewBox="0 0 1200 630">
    <rect width="1200" height="630" fill="#171512"/>
    <rect width="1200" height="8" fill="#d69b42"/>
    <g font-family="Space Grotesk">
      <text x="64" y="85" font-size="30" fill="#d69b42">mr boxington / docs</text>
      ${heading}
      <path d="M64 508 H1136" stroke="#4b3c29"/>
      <text x="64" y="564" font-size="26" fill="#c2b6a4">mr-boxington.jdx.dev</text>
      <text x="1136" y="564" text-anchor="end" font-size="26" fill="#d69b42">fix target/</text>
    </g>
    <image x="855" y="145" width="280" height="280" xlink:href="data:image/svg+xml;base64,${Buffer.from(logo).toString("base64")}"/>
  </svg>`;
  const hash = createHash("sha256").update(svg).update(readFileSync(fontFile)).digest("hex").slice(0, 16);
  return { svg, path: `social/${hash}.png` };
}

export function writeSocialCard(outDir, card) {
  const image = new Resvg(card.svg, { font: { fontFiles: [fontFile], loadSystemFonts: false } }).render().asPng();
  mkdirSync(resolve(outDir, "social"), { recursive: true });
  writeFileSync(resolve(outDir, card.path), image);
}
